#include <cctype>
#include <iostream>
#include <string>

bool texto_admitido(const std::string& texto) {
    if (texto.size() > 40) { return false; }
    for (char caracter : texto) {
        if (static_cast<unsigned char>(caracter) > 127) { return false; }
    }
    return true;
}

struct Resumen_caracteres {
    int letras;
    int digitos;
    int blancos;
    int otros;
};

Resumen_caracteres resumir(const std::string& texto) {
    Resumen_caracteres resultado{0, 0, 0, 0};
    for (char caracter : texto) {
        const unsigned char unidad = static_cast<unsigned char>(caracter);
        if (std::isalpha(unidad) != 0) { ++resultado.letras; }
        else if (std::isdigit(unidad) != 0) { ++resultado.digitos; }
        else if (std::isspace(unidad) != 0) { ++resultado.blancos; }
        else { ++resultado.otros; }
    }
    return resultado;
}

std::string copiar_en_minusculas(const std::string& texto) {
    std::string resultado = texto;
    for (char& caracter : resultado) {
        caracter = static_cast<char>(std::tolower(static_cast<unsigned char>(caracter)));
    }
    return resultado;
}

std::string copiar_en_mayusculas(const std::string& texto) {
    std::string resultado = texto;
    for (char& caracter : resultado) {
        caracter = static_cast<char>(std::toupper(static_cast<unsigned char>(caracter)));
    }
    return resultado;
}

int main() {
    std::string entrada{"CaJa 2."};
    const std::string previo = entrada;
    if (!texto_admitido(entrada)) {
        std::cout << "Texto rechazado";
        return 0;
    }
    const Resumen_caracteres resumen = resumir(entrada);
    const std::string minusculas = copiar_en_minusculas(entrada);
    const std::string mayusculas = copiar_en_mayusculas(entrada);
    std::cout << "Original:<" << entrada << ">\n"
              << "Minusculas:<" << minusculas << ">\n"
              << "Mayusculas:<" << mayusculas << ">\n"
              << "Letras:" << resumen.letras << ";Digitos:" << resumen.digitos
              << ";Blancos:" << resumen.blancos << ";Otros:" << resumen.otros
              << "\nEntrada conservada:" << (entrada == previo);
    return 0;
}

